// ==UserScript==
// @name         google-search probe
// @match        *://www.google.com/search*
// @connect      127.0.0.1
// @grant        GM_xmlhttpRequest
// @run-at       document-start
// ==/UserScript==
/* @detect */
function browseDetect(facts) {
  if (facts.isGoogleSerp && (facts.hasTurnstile || facts.hasChallengeDom)) {
    return { slug: 'google-search', confidence: 'PLAUSIBLE' };
  }
  return null;
}
/* @enddetect */
