// 判读(consent/challenge/空 SERP)+ SERP 主选择器/启发式兜底双道 + mdream 摘要;
// 主断言 = documentElement.setAttribute('probe', JSON)(G001 §5,跨世界共享)。
// 完成信号(用户令 con-06):结果指纹稳定即收齐 → attr 带 settled:true + /events 回调一次(携 url 列表),
// mech 侧挂 attr 观察器拿到即走,不计时轮询;md 异步补写不卡信号。目标页访问走 mech cdp 开标签道(v3)。
// 调试面:payload.probe_debug 时间线(注入/指纹变化/settle 触发原因/md 各态),挂起直读 attr 定位。
(function () {
  'use strict';
  var SELECTORS_VERSION = '2026-10-10.3';
  var INTERNAL = /^(?:[a-z0-9-]+\.)*(?:google\.[a-z.]+|googleusercontent\.com|gstatic\.com|ggpht\.com|youtube\.[a-z.]+|blogger\.com|googleadservices\.com|doubleclick\.net)\//i;
  var GOTO = /^https:\/\/www\.google\.com\/goto\?url=/;
  var PORT = (function () { var p = '%%BROWSE_PORT%%'; return p.indexOf('%%') === 0 ? '9880' : p; })();
  var STARTED = Date.now();
  var lastMut = Date.now();
  var mo = null;
  var reported = false;

  // 调试时间线(环形 24 条,随 attr 出)
  var DBG = [];
  function dbg(ev) {
    DBG.push({ t: Date.now() - STARTED, ev: String(ev).slice(0, 60) });
    if (DBG.length > 24) DBG.shift();
  }
  dbg('inject:readyState=' + document.readyState);

  function unwrap(u) {
    if (u && u.indexOf('/url?') === 0) {
      try { return new URL(u, location.origin).searchParams.get('q') || u; } catch (e) { return u; }
    }
    return u;
  }

  function judge(nResults) {
    if (document.querySelector('#consent, form[action*="consent"], div[aria-modal="true"] form[action*="consent"]')) return 'consent';
    if (document.querySelector('.cf-turnstile,#challenge-running,.g-recaptcha,.h-captcha') || location.pathname.indexOf('/sorry') === 0) return 'challenged';
    if (nResults === 0) return 'empty';
    return 'ok';
  }

  function push(out, seen, a, h, via) {
    var href = unwrap(a.href || a.getAttribute('href') || '');
    if (!/^https?:\/\//i.test(href)) return;
    // /goto?url= 是 SERP 结果包装(2026-10 新形,服务端跟跳),不是内链:放行并打标
    var wrapped = GOTO.test(href) ? 'goto' : null;
    if (!wrapped && INTERNAL.test(href.replace(/^https?:\/\//i, ''))) return;
    if (seen[href]) return;
    seen[href] = 1;
    var cont = a.closest('div[data-hveid], div.g, div.MjjYud') || a.parentElement;
    var sn = cont ? String(cont.innerText || '').replace(/\s+/g, ' ').trim().slice(0, 300) : '';
    out.push({ title: String(h.innerText || '').trim(), url: href, wrapped: wrapped, snippet: sn, via: via });
  }

  // 主道:SERP 容器内 h3 取锚(现代 Google 结果形)
  function pickMain() {
    var out = [], seen = {};
    var hs = document.querySelectorAll('#search h3, #rso h3, div#main h3');
    for (var i = 0; i < hs.length && out.length < 20; i++) {
      var a = hs[i].closest('a[href]');
      if (a) push(out, seen, a, hs[i], 'main');
    }
    return out;
  }

  // 兜底道:外链锚含 h3 的启发式(主道漂移时顶上,命中记 drift=suspected)
  function pickFallback() {
    var out = [], seen = {};
    var as = document.querySelectorAll('#search a[href], #rso a[href], div#main a[href], main a[href]');
    for (var i = 0; i < as.length && out.length < 20; i++) {
      var h = as[i].querySelector('h3, [role="heading"]');
      if (h) push(out, seen, as[i], h, 'fallback');
    }
    return out;
  }

  // 完成回调:报 daemon /events 一次(携完整 url 列表;type 两档 see/stop,G001 §6 形)
  function reportSettled(payload) {
    if (reported) return;
    reported = true;
    dbg('report:events');
    try {
      GM_xmlhttpRequest({
        method: 'POST',
        url: 'http://127.0.0.1:' + PORT + '/events',
        headers: { 'Content-Type': 'application/json' },
        data: JSON.stringify({
          type: 'see', slug: 'google-search', action: 'read', url: location.href,
          data: { verdict: payload.verdict, count: payload.results.length, settled: true, urls: payload.results.map(function (r) { return r.url; }) }
        }),
        onerror: function () { dbg('report:error'); }
      });
    } catch (e) { dbg('report:throw'); }
  }

  // md 公共执行器:mdream IIFE 实测回 Promise 且 d.ts 声 string 不可信;竞速帽防挂死。
  // 降级链 minimal(isolateMain 对 SERP 常取空)→ clean → plain。
  function mdRace(p, ms) {
    return Promise.race([Promise.resolve(p), new Promise(function (_, rej) { setTimeout(function () { rej(new Error('mdream-timeout')); }, ms); })]);
  }
  async function mdConvertOnce(html, opts) {
    var raw = await mdRace(window.mdream.htmlToMarkdown(html, opts), 4000);
    if (typeof raw === 'string') return raw;
    if (raw && typeof raw === 'object' && typeof raw.markdown === 'string') return raw.markdown;
    return null;
  }
  async function mdConvert(html, origin) {
    if (!(window.mdream && typeof window.mdream.htmlToMarkdown === 'function')) return { markdown: null, converter: 'failed', debug: { err: 'mdream-absent' } };
    var chain = [
      { shape: 'minimal', opts: { minimal: true, origin: origin || location.origin } },
      { shape: 'clean', opts: { clean: true, origin: origin || location.origin } },
      { shape: 'plain', opts: {} }
    ];
    for (var ci = 0; ci < chain.length; ci++) {
      dbg('md:run:' + chain[ci].shape);
      try {
        var md = await mdConvertOnce(html, chain[ci].opts);
        if (md && md !== '[object Object]') {
          dbg('md:done:' + chain[ci].shape + ':len=' + md.length);
          return { markdown: md, converter: 'mdream@2.0.1/' + chain[ci].shape, debug: null };
        }
      } catch (e) {
        dbg('md:err:' + chain[ci].shape);
        return { markdown: null, converter: /timeout/.test(String(e)) ? 'failed(timeout)' : 'failed', debug: { err: String(e).slice(0, 120) } };
      }
    }
    return { markdown: null, converter: 'failed', debug: { err: 'all-shapes-empty' } };
  }

  // 目标页并行抓取(mech 经 probe attr 通道请求与收果,con-06-add1 架构):
  // mech 写 probe-req {id, urls};探针 GM_xmlhttpRequest 并行抓 + mdream 并行转,
  // 结果写 probe-pages {id, pages}。单页 15s 帽,html 500K 帽,markdown 24K 帽。
  // SERP 摘要异步补写:settled 终写不等待 mdream,不卡收齐信号
  var mdKicked = false;
  function enrichMd() {
    if (mdKicked) return;
    mdKicked = true;
    dbg('md:kick');
    (async function () {
      var out = await mdConvert(document.documentElement.outerHTML, location.origin);
      try {
        var cur = JSON.parse(document.documentElement.getAttribute('probe') || 'null');
        if (cur && cur.slug === 'google-search') {
          cur.markdown = out.markdown;
          cur.converter = out.converter;
          if (out.debug) cur.md_debug = out.debug;
          cur.md_ts = Date.now();
          cur.probe_debug = DBG.slice();
          document.documentElement.setAttribute('probe', JSON.stringify(cur));
          dbg('md:merged');
        }
      } catch (e) { dbg('md:merge-throw'); }
    })();
  }

  function collect(forceSettled) {
    var main = pickMain();
    var fb = main.length === 0 ? pickFallback() : [];
    var all = main.length > 0 ? main : fb;
    var verdict = judge(all.length);
    var drift = main.length === 0 && fb.length > 0 ? 'suspected' : 'none';
    var settled = (forceSettled !== undefined) ? forceSettled
      : ((Date.now() - lastMut >= 800) || (Date.now() - STARTED >= 12000));
    var payload = {
      slug: 'google-search',
      v: SELECTORS_VERSION,
      verdict: verdict,
      drift: drift,
      mainHits: main.length,
      fallbackHits: fb.length,
      results: all.slice(0, 10),
      url: location.href,
      title: document.title,
      ts: Date.now(),
      settled: settled,
      markdown: null,
      converter: verdict === 'ok' ? 'mdream-pending' : ('skipped-' + verdict),
      probe_debug: DBG.slice()
    };
    try {
      document.documentElement.setAttribute('probe', JSON.stringify(payload));
    } catch (e) { dbg('attr:throw'); }
    if (settled) {
      if (mo) { mo.disconnect(); mo = null; }
      reportSettled(payload);
      enrichMd(); // 异步补写 md,不卡收齐信号
    }
  }

  // 收集期(document-start 早注入;interval 驱动,变更只记时不排程——Google SERP
  // 动画变更持续,去抖排程会被饿死)。链接在页即出 attr(指纹变即中间写,mech/人早见)。
  // 收齐判定 = 结果指纹稳定 ≥500ms(非零)或 readyState-complete 且 DOM 静默 800ms 或 12s 硬帽;
  // settled 即断 interval 与观察器、collect(true) 终写、/events 回调一次、md 异步补写。
  var lastFp = null;
  var lastFpAt = 0;
  var finalized = false;
  var iv = null;
  mo = new MutationObserver(function () { lastMut = Date.now(); });
  mo.observe(document.documentElement, { childList: true, subtree: true });
  iv = setInterval(function () {
    if (finalized) return;
    var now = Date.now();
    var fp = JSON.stringify(pickMain().map(function (r) { return r.url; }));
    if (fp !== lastFp) {
      dbg('fp:' + JSON.parse(fp).length);
      lastFp = fp; lastFpAt = now;
      collect(false); // 中间写:链接在页即见(verdict/results 即时,md 不跑)
      return;
    }
    var stable = (now - lastFpAt) >= 500 && JSON.parse(fp).length > 0;
    var pageDone = document.readyState === 'complete' && (now - lastMut) >= 800;
    if (stable || pageDone || (now - STARTED) >= 12000) {
      finalized = true;
      dbg('settle:' + (stable ? 'stable' : (pageDone ? 'pageDone' : 'cap12s')));
      if (iv !== null) { clearInterval(iv); iv = null; }
      collect(true);
    }
  }, 250);
})();
